contracts/StakeForNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./UyArt.sol";

contract StakeForNFT {

    IERC20 public immutable token;
    UyArt public immutable nft;

    // Variables de limites
    uint256 public deployedBlock;
    uint256 public constant STAKING_WINDOW = 1000; // Blocks
    uint256 public constant MIN_STAKE_AMOUNT = 1000 * 10**18; // 1000 tokens con 18 decimales
    uint256 public constant MAX_TOTAL_STAKED = 100000 * 10**18; // 100,000 tokens con 18 decimales

    uint256 public totalStaked = 0;
    bool public nftDistributed = false;

    struct StakeRecord {
        uint256 balance;
        uint256 blockNumber;
        bool claimed;
    }

    mapping(address => StakeRecord) public stakes;

    event Staked(address indexed user, uint256 amount);
    event NFTClaimed(address indexed user, uint256 amount, uint256 firstTokenId);

    /**
     * @param _tokenAddress address del token ERC20 para staking (OrtToken)
     * @param _nftAddress address del contrato UyArt NFT
     */
    constructor(address _tokenAddress, address _nftAddress) {
        require(_tokenAddress != address(0), "La direccion del token no puede ser vacia");
        require(_nftAddress != address(0), "La direccion del NFT no puede ser vacia");

        token = IERC20(_tokenAddress);
        nft = UyArt(_nftAddress);
        deployedBlock = block.number;
    }

    /**
     * @notice Stake `amount` tokens. El usuario debe invocar 'approve' en el token primero
     * @param amount numero de tokens a stakear (debe ser multiplo de 1000)
     */
    function stake(uint256 amount) external {
        require(block.number <= deployedBlock + STAKING_WINDOW, "Periodo de staking finalizado");
        require(amount >= MIN_STAKE_AMOUNT, "El monto debe ser al menos 1000 tokens");
        require(amount % MIN_STAKE_AMOUNT == 0, "El monto debe ser multiplo de 1000 tokens");
        require(totalStaked + amount <= MAX_TOTAL_STAKED, "Excede el maximo total de staking");

        // Transferir tokens al contrato
        bool ok = token.transferFrom(msg.sender, address(this), amount);
        require(ok, "Error en transferencia de tokens");

        // Actualizar el registro de stake
        StakeRecord storage rec = stakes[msg.sender];
        rec.balance += amount;
        rec.blockNumber = block.number;
        rec.claimed = false;

        // Actualizar total
        totalStaked += amount;

        // Emitir evento de stake   
        emit Staked(msg.sender, amount);
    }

    /**
     * @notice Permite a los usuarios reclamar sus NFTs despues del periodo de staking
     */
    function claimNFTs() external {
        require(block.number > deployedBlock + STAKING_WINDOW, "Periodo de staking aun no finalizado");

        StakeRecord storage rec = stakes[msg.sender];
        uint256 balance = rec.balance;

        require(balance >= MIN_STAKE_AMOUNT, "No tiene suficientes tokens en stake");
        require(!rec.claimed, "NFTs ya reclamados");

        // Calcular cuantos NFTs recibe
        uint256 nftAmount = balance / MIN_STAKE_AMOUNT;

        // Marcar como reclamado
        rec.claimed = true;

        // Mintear los NFTs para el usuario
        uint256 firstTokenId = mintNFTsToUser(msg.sender, nftAmount);

        // Emitir evento
        emit NFTClaimed(msg.sender, nftAmount, firstTokenId);
    }

    /**
     * @dev Funcion interna para mintear NFTs a un usuario
     */
    function mintNFTsToUser(address user, uint256 amount) private returns (uint256) {
        // Asumimos que el contrato UyArt tiene una funcion para mintear NFTs
        uint256 firstTokenId = 0;

        for (uint256 i = 0; i < amount; i++) {
            // Generar metadata unica para cada NFT
            string memory metadata = generateMetadata(user, i);

            // Mintear el NFT y guardar el primer ID
            uint256 tokenId = _mintNFT(user, metadata);
            if (i == 0) {
                firstTokenId = tokenId;
            }
        }

        return firstTokenId;
    }

    /**
     * @dev Funcion para generar metadatos para el NFT
     */
    function generateMetadata(address user, uint256 index) private pure returns (string memory) {
        // En una implementacion real, generarias un JSON estructurado y lo subirias a IPFS
        // Para esta implementacion, simplemente creamos un string unico
        return string(abi.encodePacked("UyArt_", toHexString(user), "_", uint2str(index)));
    }

    /**
     * @dev Funcion para mintear un NFT utilizando el contrato UyArt
     */
    function _mintNFT(address to, string memory metadata) private returns (uint256) {
        return nft.mint(to, metadata);
    }

    /**
     * @dev Convierte un uint a string
     */
    function uint2str(uint256 _i) internal pure returns (string memory) {
        if (_i == 0) {
            return "0";
        }
        uint256 j = _i;
        uint256 length;
        while (j != 0) {
            length++;
            j /= 10;
        }
        bytes memory bstr = new bytes(length);
        uint256 k = length;
        while (_i != 0) {
            k = k-1;
            uint8 temp = (48 + uint8(_i - _i / 10 * 10));
            bytes1 b1 = bytes1(temp);
            bstr[k] = b1;
            _i /= 10;
        }
        return string(bstr);
    }

    /**
     * @dev Convierte una direccion a string hexadecimal
     */
    function toHexString(address addr) internal pure returns (string memory) {
        bytes memory buffer = new bytes(40);
        for (uint256 i = 0; i < 20; i++) {
            bytes1 b = bytes1(uint8(uint256(uint160(addr)) / (2**(8*(19 - i)))));
            bytes1 hi = bytes1(uint8(b) / 16);
            bytes1 lo = bytes1(uint8(b) - 16 * uint8(hi));
            buffer[2*i] = char(hi);
            buffer[2*i+1] = char(lo);            
        }
        return string(buffer);
    }

    /**
     * @dev Convierte un byte a su representacion hexadecimal
     */
    function char(bytes1 b) internal pure returns (bytes1 c) {
        if (uint8(b) < 10) return bytes1(uint8(b) + 0x30);
        else return bytes1(uint8(b) + 0x57);
    }
}

contracts/UyArt.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/**
 * @title UyArt
 * @dev Implementacion del estandar ERC721 para NFT de arte uruguayo
 * Basado en: https://eips.ethereum.org/EIPS/eip-721
 */
contract UyArt {
    // Nombre y simbolo del NFT
    string private _name = "Uruguay Art Collection";
    string private _symbol = "UYART";

    // Contador de tokens
    uint256 private _tokenIdCounter = 1;
    uint256 private constant MAX_SUPPLY = 100;

    // Direccion del contrato de staking autorizado
    address public stakingContract;
    address public owner;

    // Mapping de tokenId a propietario
    mapping(uint256 => address) private _owners;

    // Mapping de propietario a cantidad de tokens
    mapping(address => uint256) private _balances;

    // Mapping de tokenId a URI con metadatos
    mapping(uint256 => string) private _tokenURIs;

    // Mapping de tokenId a direcciones aprobadas
    mapping(uint256 => address) private _tokenApprovals;

    // Mapping de propietario a operador aprobado
    mapping(address => mapping(address => bool)) private _operatorApprovals;

    /**
     * @dev Emitido cuando se transfiere el `tokenId` de `from` a `to`
     */
    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);

    /**
     * @dev Emitido cuando `owner` permite a `approved` administrar el `tokenId`
     */
    event Approval(address indexed owner, address indexed approved, uint256 indexed tokenId);

    /**
     * @dev Emitido cuando `owner` habilita o deshabilita a `operator` para administrar todos sus tokens
     */
    event ApprovalForAll(address indexed owner, address indexed operator, bool approved);

    constructor() {
        owner = msg.sender;
    }

    /**
     * @dev Configura el contrato de staking autorizado
     */
    function setStakingContract(address _stakingContract) external {
        require(msg.sender == owner, "UyArt: solo el propietario puede configurar el contrato de staking");
        stakingContract = _stakingContract;
    }

    /**
     * @dev Devuelve el nombre del token
     */
    function name() external view returns (string memory) {
        return _name;
    }

    /**
     * @dev Devuelve el simbolo del token
     */
    function symbol() external view returns (string memory) {
        return _symbol;
    }

    /**
     * @dev Devuelve el URI de metadatos para un tokenId específico
     */
    function tokenURI(uint256 tokenId) external view returns (string memory) {
        require(_exists(tokenId), "UyArt: consulta para token inexistente");
        string memory baseURI = _baseURI();

        if (bytes(_tokenURIs[tokenId]).length > 0) {
            return string(abi.encodePacked(baseURI, _tokenURIs[tokenId]));
        }

        return baseURI;
    }

    /**
     * @dev URI base para completar los metadatos tokenURI
     */
    function _baseURI() internal pure returns (string memory) {
        return "ipfs://";
    }

    /**
     * @dev Devuelve la cantidad de tokens en la cuenta de `owner`
     */
    function balanceOf(address owner) external view returns (uint256) {
        require(owner != address(0), "UyArt: balance consulta para address cero");
        return _balances[owner];
    }

    /**
     * @dev Devuelve el propietario del `tokenId`
     */
    function ownerOf(uint256 tokenId) public view returns (address) {
        address owner = _owners[tokenId];
        require(owner != address(0), "UyArt: propietario consulta para token inexistente");
        return owner;
    }

    /**
     * @dev Transfiere el `tokenId` de `from` a `to`
     */
    function _transfer(address from, address to, uint256 tokenId) internal {
        require(ownerOf(tokenId) == from, "UyArt: transferencia de token no poseido");
        require(to != address(0), "UyArt: transferencia a address cero");

        // Eliminar aprobaciones
        _approve(address(0), tokenId);

        // Actualizar balances
        _balances[from]--;
        _balances[to]++;

        // Actualizar propietario
        _owners[tokenId] = to;

        // Emitir evento
        emit Transfer(from, to, tokenId);
    }

    /**
     * @dev Transfiere el `tokenId` de `from` a `to`
     */
    function transferFrom(address from, address to, uint256 tokenId) external {
        require(_isApprovedOrOwner(msg.sender, tokenId), "UyArt: transferencia no autorizada");
        _transfer(from, to, tokenId);
    }

    /**
     * @dev Transfiere el `tokenId` de `from` a `to` de forma segura, verificando que `to` puede recibir NFTs
     * En nuestra implementacion basica es igual a transferFrom
     */
    function safeTransferFrom(address from, address to, uint256 tokenId) external {
        safeTransferFrom(from, to, tokenId, "");
    }

    /**
     * @dev Transfiere el `tokenId` de `from` a `to` de forma segura con datos adicionales
     */
    function safeTransferFrom(address from, address to, uint256 tokenId, bytes memory data) public {
        require(_isApprovedOrOwner(msg.sender, tokenId), "UyArt: transferencia no autorizada");
        _transfer(from, to, tokenId);

        // Aqui normalmente se verificaria si el destinatario es un contrato y si puede recibir NFTs
        // Para simplificar nuestra implementacion, omitimos esta verificacion
        // Esta es la principal diferencia con una implementacion completa del ERC721
    }

    /**
     * @dev Aprueba a `to` para transferir el `tokenId`
     */
    function approve(address to, uint256 tokenId) external {
        address owner = ownerOf(tokenId);
        require(to != owner, "UyArt: aprobacion al propietario actual");
        require(
            msg.sender == owner || isApprovedForAll(owner, msg.sender),
            "UyArt: no aprobado para todos"
        );

        _approve(to, tokenId);
    }

    /**
     * @dev Funcion interna para aprobar
     */
    function _approve(address to, uint256 tokenId) internal {
        _tokenApprovals[tokenId] = to;
        emit Approval(ownerOf(tokenId), to, tokenId);
    }

    /**
     * @dev Devuelve la direccion aprobada para un `tokenId` especifico
     */
    function getApproved(uint256 tokenId) external view returns (address) {
        require(_exists(tokenId), "UyArt: aprobado consulta para token inexistente");
        return _tokenApprovals[tokenId];
    }

    /**
     * @dev Aprueba o desaprueba al `operator` para transferir todos los tokens del remitente
     */
    function setApprovalForAll(address operator, bool approved) external {
        require(operator != msg.sender, "UyArt: aprobacion a uno mismo");
        _operatorApprovals[msg.sender][operator] = approved;
        emit ApprovalForAll(msg.sender, operator, approved);
    }

    /**
     * @dev Devuelve si el `operator` esta autorizado para administrar todos los tokens de `owner`
     */
    function isApprovedForAll(address owner, address operator) public view returns (bool) {
        return _operatorApprovals[owner][operator];
    }

    /**
     * @dev Verifica si la direccion tiene permisos para transferir un token
     */
    function _isApprovedOrOwner(address spender, uint256 tokenId) internal view returns (bool) {
        require(_exists(tokenId), "UyArt: operador consulta para token inexistente");
        address owner = ownerOf(tokenId);
        return (spender == owner || _tokenApprovals[tokenId] == spender || isApprovedForAll(owner, spender));
    }

    /**
     * @dev Verifica si el token existe
     */
    function _exists(uint256 tokenId) internal view returns (bool) {
        return _owners[tokenId] != address(0);
    }

    /**
     * @dev Funcion publica para mintear un nuevo token NFT (solo contrato de staking puede llamarlo)
     */
    function mint(address to, string memory tokenMetadata) external returns (uint256) {
        require(msg.sender == stakingContract, "UyArt: solo el contrato de staking puede mintear");
        return _mint(to, tokenMetadata);
    }

    /**
     * @dev Funcion interna para mintear un nuevo token NFT
     */
    function _mint(address to, string memory tokenMetadata) internal returns (uint256) {
        require(to != address(0), "UyArt: minteo a la direccion cero");
        require(_tokenIdCounter <= MAX_SUPPLY, "UyArt: Superado el maximo supply");

        uint256 tokenId = _tokenIdCounter;
        _tokenIdCounter++;

        _balances[to]++;
        _owners[tokenId] = to;

        if (bytes(tokenMetadata).length > 0) {
            _tokenURIs[tokenId] = tokenMetadata;
        }

        emit Transfer(address(0), to, tokenId);

        return tokenId;
    }

    /**
     * @dev Retorna la cantidad total de tokens minteados
     */
    function totalSupply() external view returns (uint256) {
        return _tokenIdCounter - 1;
    }

    /**
     * @dev Retorna el supply maximo
     */
    function maxSupply() external pure returns (uint256) {
        return MAX_SUPPLY;
    }

    /**
     * @dev Funcion para crear la URI con metadatos para un tokenId
     */
    function generateTokenURI(string memory imageHash) internal pure returns (string memory) {
        return imageHash;
    }
}

